-- Character schema 1; predecessor migration 4; engine runtime 4/API 3.
-- Engine wraps this script, checks and checksum receipt in one transaction.
CREATE UNIQUE INDEX IF NOT EXISTS events_identity_compat ON events(id);
CREATE TABLE IF NOT EXISTS "character_identity"(branch TEXT NOT NULL,id TEXT NOT NULL,"character" TEXT NOT NULL,"existence" TEXT NOT NULL CHECK("existence" IN ('established','provisional','alleged')),"canonical_name" TEXT,"name_status" TEXT NOT NULL CHECK("name_status" IN ('known','unknown','absent','not_applicable')),"continuity" TEXT NOT NULL CHECK("continuity" IN ('established','disputed','unresolved','transformed')),PRIMARY KEY(branch,id),FOREIGN KEY(branch,id) REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"character") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "character_aspect"(branch TEXT NOT NULL,id TEXT NOT NULL,"character" TEXT NOT NULL,"section" TEXT NOT NULL CHECK("section" IN ('nature','interiority','portrayal','condition','perspective','development')),"kind" TEXT NOT NULL CHECK("kind" IN ('facet','embodiment','constituent','principle','drive','commitment','preference','boundary','conflict','description','voice','mannerism','habit','pleasure','attachment','injury','fatigue','memory_disruption','recognition_disruption','intention_impairment','agency_constraint','communication','memory','question')),"value_status" TEXT NOT NULL CHECK("value_status" IN ('known','unknown','absent','not_applicable')),"statement" TEXT,"related_character" TEXT,"related_item" TEXT,"clock" TEXT,"valid_from" REAL,"valid_until" REAL,"ending_condition" TEXT,"phase" TEXT NOT NULL CHECK("phase" IN ('active','ended')),"change_basis" TEXT NOT NULL CHECK("change_basis" IN ('established','voluntary','compelled','deceived','disrupted','recovered','unknown')),"supersedes" TEXT,PRIMARY KEY(branch,id),FOREIGN KEY(branch,id) REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"character") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"related_character") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"related_item") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"clock") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"supersedes") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "character_presence"(branch TEXT NOT NULL,id TEXT NOT NULL,"character" TEXT NOT NULL,"location" TEXT NOT NULL,"embodiment" TEXT,"mode" TEXT NOT NULL CHECK("mode" IN ('physical','projected','distributed','unknown')),"phase" TEXT NOT NULL CHECK("phase" IN ('present','departed','uncertain')),PRIMARY KEY(branch,id),FOREIGN KEY(branch,id) REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"character") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"location") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"embodiment") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "character_lineage"(branch TEXT NOT NULL,id TEXT NOT NULL,"predecessor" TEXT NOT NULL,"successor" TEXT NOT NULL,"relation" TEXT NOT NULL CHECK("relation" IN ('origin','split','merge','succession','copy','fragment','disputed')),"explanation" TEXT NOT NULL,PRIMARY KEY(branch,id),FOREIGN KEY(branch,id) REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"predecessor") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"successor") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED);
CREATE UNIQUE INDEX IF NOT EXISTS one_character_identity ON character_identity(branch,character);
INSERT INTO engine_versions(component,version) VALUES('character_schema','1');
